577	                    DiffStatusMessage = string.Format(Texts.ModAlreadyRemovedStatus, line.FileName);
578	                }
579	            }
580	            catch (Exception ex)
581	            {
582	                DiffStatusMessage = string.Format(Texts.FailedToRemoveError, line.FileName) + " " + ex.Message;
583	            }
584	        }
