586	        private async Task ReplaceRemovedModAsync((DiffLineModel Removed, DiffLineModel Replacement) request)
587	        {
588	            var (removed, replacement) = request;
589	            if (removed is null || replacement is null)
590	            {
591	                return;
592	            }
593	
594	            if (removed.ChangeType != DiffChangeType.Removed || replacement.ChangeType != DiffChangeType.Added)
595	            {
596	                return;
597	            }
598	
599	            try
600	            {
601	                bool changed = await FileService.ReplaceModWithNewAsync(_mainViewModel.Config, removed.FileName, replacement.FileName);
602	                if (changed)
603	                {
604	                    DiffStatusMessage = string.Format(Texts.ReplacedModStatus, removed.FileName, replacement.FileName);
605	                    await RefreshDiffAsync(DiffStatusMessage);
606	                }
607	                else
608	                {
609	                    DiffStatusMessage = string.Format(Texts.ModNoLongerPendingStatus, replacement.FileName);
610	                }
611	            }
612	            catch (Exception ex)
613	            {
614	                DiffStatusMessage = string.Format(Texts.FailedToReplaceError, removed.FileName) + " " + ex.Message;
615	            }
616	        }
