618	        private bool CanUpdateReference()
619	        {
620	            return _mainViewModel?.CreateReferenceCommand?.CanExecute(null) ?? false;
621	        }
622	
623	        /// <summary>
624	        /// Builds a risk-specific confirmation message based on the current diff state.
625	        /// Returns <c>null</c> when no confirmation is needed (safe-only changes).
626	        /// </summary>
627	        internal string? BuildConfirmationMessage()
628	        {
629	            var removedCount = DiffLines.Count(line => line.ChangeType == DiffChangeType.Removed);
630	            var insertedCount = DiffLines.Count(line => line.ChangeType == DiffChangeType.Inserted);
631	
632	            if (removedCount == 0 && insertedCount == 0)
633	                return null;
634	
635	            var detailLines = new List<string>();
636	
637	            if (removedCount > 0)
638	            {
639	                detailLines.Add(removedCount == 1
640	                    ? Texts.ConfirmRiskyDetail_RemovedSingular
641	                    : string.Format(Texts.ConfirmRiskyDetail_Removals, removedCount));
642	            }
643	
644	            if (insertedCount > 0)
645	            {
646	                detailLines.Add(insertedCount == 1
647	                    ? Texts.ConfirmRiskyDetail_InsertedSingular
648	                    : string.Format(Texts.ConfirmRiskyDetail_Insertions, insertedCount));
649	            }
650	
651	            string detailBlock = string.Join("\n", detailLines);
652	            return string.Format(Texts.ConfirmUpdateMessage_RiskyChanges, detailBlock);
653	        }
654	
655	        private async Task UpdateReferenceWithConfirmationAsync()
656	        {
657	            string? confirmMessage = BuildConfirmationMessage();
658	
659	            if (confirmMessage is not null)
660	            {
661	                var eventArgs = new ConfirmationRequestedEventArgs(
662	                    Texts.ConfirmUpdateTitle,
663	                    confirmMessage,
664	                    ConfirmationIcon.Warning,
665	                    ConfirmationButton.YesNo);
666	                ConfirmationRequested?.Invoke(this, eventArgs);
667	
668	                if (eventArgs.Result != ConfirmationResult.Yes)
669	                {
670	                    DiffStatusMessage = Texts.ReferenceUpdateCancelledStatus;
671	                    return;
672	                }
673	            }
674	
675	            // Proceed with the update
676	            if (_mainViewModel.CreateReferenceCommand?.CanExecute(null) ?? false)
677	            {
678	                await _mainViewModel.CreateReferenceCommand.ExecuteAsync(null);
679	            }
680	        }
